DE_MURA4 = {
    ('Text/Event/Mura/Fumoto/EventMain.csvtxt', 'English#c:02000301_0'): 'Was macht ihr alle da draußen\nvor dem Bergpass?',
    ('Text/Event/Mura/Fumoto/EventMain.csvtxt', 'English#c:02000301_1'): 'Willkommen zurück, Lady Sakuna.',
    ('Text/Event/Mura/Fumoto/EventMain.csvtxt', 'English#c:02000301_10'): 'Ich finde es eine großartige Idee. Vergrößern wir unsere\nFelder so sehr, wird die Reisernte im Herbst\nexponentiell steigen.',
    ('Text/Event/Mura/Fumoto/EventMain.csvtxt', 'English#c:02000301_11'): 'Es hat sich gelohnt, den harten Winter zu ertragen\nund die geernteten Samen aufzuheben.',
    ('Text/Event/Mura/Fumoto/EventMain.csvtxt', 'English#c:02000301_12'): '*keucht* *keucht*',
    ('Text/Event/Mura/Fumoto/EventMain.csvtxt', 'English#c:02000301_13'): 'Es hört nie auf. Mein Rücken ist Schmerz\nin Person. Ich arbeite ununterbrochen\nund hier bin ich schon wieder.',
    ('Text/Event/Mura/Fumoto/EventMain.csvtxt', 'English#c:02000301_14'): '...',
    ('Text/Event/Mura/Fumoto/EventMain.csvtxt', 'English#c:02000301_15'): 'Dir geht es nicht als Einziger beschissen.',
    ('Text/Event/Mura/Fumoto/EventMain.csvtxt', 'English#c:02000301_16'): 'Wiiih! Wiiih!',
    ('Text/Event/Mura/Fumoto/EventMain.csvtxt', 'English#c:02000301_17'): 'Hör auf, Kaimaru.\nGeh dort spielen.',
    ('Text/Event/Mura/Fumoto/EventMain.csvtxt', 'English#c:02000301_18'): 'Ihr geht ja nicht zum Jagen.\nIhr habt keine Ahnung, wie hart das für mich ist.',
    ('Text/Event/Mura/Fumoto/EventMain.csvtxt', 'English#c:02000301_19'): 'Was für ein Quatsch. Wer meinst du, hat\ndiese Felder umgepflügt, Lady?',
    ('Text/Event/Mura/Fumoto/EventMain.csvtxt', 'English#c:02000301_2'): 'Dank deiner Bemühungen bewohnen die Dämonen diesen Ort\nnicht mehr, also haben wir beschlossen, am Fuß des\nBerges Felder anzulegen.',
    ('Text/Event/Mura/Fumoto/EventMain.csvtxt', 'English#c:02000301_20'): 'Alle arbeiten sich hier den Hintern ab.\nDu warst nur nie dabei, um es zu sehen.',
    ('Text/Event/Mura/Fumoto/EventMain.csvtxt', 'English#c:02000301_21'): 'Keine Streitereien. Habt Spaß beim Pflanzen!',
    ('Text/Event/Mura/Fumoto/EventMain.csvtxt', 'English#c:02000301_22'): 'Viel Spaß!',
    ('Text/Event/Mura/Fumoto/EventMain.csvtxt', 'English#c:02000301_23'): 'Wie soll man bei HANDARBEIT Spaß haben?!',
    ('Text/Event/Mura/Fumoto/EventMain.csvtxt', 'English#c:02000301_24'): 'Hör auf, den Mund zu bewegen, und lass deine\nHände arbeiten! Pff!',
    ('Text/Event/Mura/Fumoto/EventMain.csvtxt', 'English#c:02000301_25'): 'Wiiih! Wiiih!',
    ('Text/Event/Mura/Fumoto/EventMain.csvtxt', 'English#c:02000301_26'): 'Wa--?!',
    ('Text/Event/Mura/Fumoto/EventMain.csvtxt', 'English#c:02000301_27'): 'Du Holzkopf!',
    ('Text/Event/Mura/Fumoto/EventMain.csvtxt', 'English#c:02000301_28'): 'Waaaaah!',
    ('Text/Event/Mura/Fumoto/EventMain.csvtxt', 'English#c:02000301_29'): 'Hey, Rotzlöffel! Zeig etwas Respekt\nvor deinen Göttern und Älteren!',
    ('Text/Event/Mura/Fumoto/EventMain.csvtxt', 'English#c:02000301_3'): 'Ashigumo hält Wache im Gebiet,\num unsere Sicherheit bei der Arbeit zu gewährleisten.',
    ('Text/Event/Mura/Fumoto/EventMain.csvtxt', 'English#c:02000301_30'): 'Wenn du dich so aufspielst, warum verdienst du\ndiesen Respekt nicht einfach, indem du hier\netwas arbeitest?!',
    ('Text/Event/Mura/Fumoto/EventMain.csvtxt', 'English#c:02000301_31'): 'Hör schon auf!\nIch bin so nah daran, dich wieder zu schlagen!',
    ('Text/Event/Mura/Fumoto/EventMain.csvtxt', 'English#c:02000301_32'): 'Hört auf, alle! Bitte hört auf!',
    ('Text/Event/Mura/Fumoto/EventMain.csvtxt', 'English#c:02000301_33'): 'Wuuuuzeler Giiier,\npersööönlische Schwäääche!',
    ('Text/Event/Mura/Fumoto/EventMain.csvtxt', 'English#c:02000301_34'): 'Füüße im Schlammm, wiiieder,\nRüüücken wääht von der Arbeit!\nFertig...',
    ('Text/Event/Mura/Fumoto/EventMain.csvtxt', 'English#c:02000301_35'): 'W-Was? Hat sein Geist den Körper verlassen?',
    ('Text/Event/Mura/Fumoto/EventMain.csvtxt', 'English#c:02000301_36'): 'Nein, das war ein Pflanzlied.',
    ('Text/Event/Mura/Fumoto/EventMain.csvtxt', 'English#c:02000301_37'): 'In der Tat. Die Feldarbeit ist eine lange, tückische\nReise, bis die Mühe belohnt wird.',
    ('Text/Event/Mura/Fumoto/EventMain.csvtxt', 'English#c:02000301_38'): 'Wenn man anfängt zu reden, beschwert man sich\nund wird niedergeschlagen. Also beschlossen\nunsere Ahnen, zu singen statt zu klagen.',
    ('Text/Event/Mura/Fumoto/EventMain.csvtxt', 'English#c:02000301_39'): 'Singen ist eine Salbe gegen die Pein der Schufterei!',
    ('Text/Event/Mura/Fumoto/EventMain.csvtxt', 'English#c:02000301_4'): 'Hmph. Dann brauche ich wohl keine Sorgen zu haben.',
    ('Text/Event/Mura/Fumoto/EventMain.csvtxt', 'English#c:02000301_40'): 'Kleeiiiner Setzliiing,\ndüünn wie ich!',
    ('Text/Event/Mura/Fumoto/EventMain.csvtxt', 'English#c:02000301_41'): 'Huh. Ich bin beeindruckt.',
    ('Text/Event/Mura/Fumoto/EventMain.csvtxt', 'English#c:02000301_42'): 'Der Alte und ich stammen aus verschiedenen Provinzen,\naber das Lied ist dasselbe, das ich kenne.\nEs geht dann weiter so, ja?',
    ('Text/Event/Mura/Fumoto/EventMain.csvtxt', 'English#c:02000301_43'): 'Wüünschend mit leeereem Maaagen,\nfür ein Feld aus Goooold!',
    ('Text/Event/Mura/Fumoto/EventMain.csvtxt', 'English#c:02000301_44'): 'Ja, das ist das richtige.\nWas meinst du, Lady Sakuna?',
    ('Text/Event/Mura/Fumoto/EventMain.csvtxt', 'English#c:02000301_45'): 'Sicher, ich versuche jetzt alles.\nBringt uns das ganze Lied bei.',
    ('Text/Event/Mura/Fumoto/EventMain.csvtxt', 'English#c:02000301_46'): "Na gut, dann! Los geht's.",
    ('Text/Event/Mura/Fumoto/EventMain.csvtxt', 'English#c:02000301_47'): 'Puh... Wie sieht das aus?',
    ('Text/Event/Mura/Fumoto/EventMain.csvtxt', 'English#c:02000301_48'): 'Wir siiind fertiiiig!',
    ('Text/Event/Mura/Fumoto/EventMain.csvtxt', 'English#c:02000301_49'): 'Juhu!',
    ('Text/Event/Mura/Fumoto/EventMain.csvtxt', 'English#c:02000301_5'): 'Hör auf zu faulenzen, Alter!\nWir müssen das bis zum Abend schaffen!',
    ('Text/Event/Mura/Fumoto/EventMain.csvtxt', 'English#c:02000301_50'): 'Wir hatten Spaß beim Reispflanzen!',
    ('Text/Event/Mura/Fumoto/EventMain.csvtxt', 'English#c:02000301_51'): 'Die Kraft des Gesangs ist wahrlich mächtig.',
    ('Text/Event/Mura/Fumoto/EventMain.csvtxt', 'English#c:02000301_52'): 'Wir sind fertig!\nJetzt heimgehen und essen!',
    ('Text/Event/Mura/Fumoto/EventMain.csvtxt', 'English#c:02000301_53'): 'Nicht so schnell, Herr Reiskopf.\nWir müssen noch das Fleisch für das Abendessen vorbereiten.',
    ('Text/Event/Mura/Fumoto/EventMain.csvtxt', 'English#c:02000301_54'): 'Natürlich wird das deine Aufgabe sein,\ndenn du hast mich gezwungen, beim Pflanzen zu helfen.',
    ('Text/Event/Mura/Fumoto/EventMain.csvtxt', 'English#c:02000301_55'): 'Waaas?!\nDas ist eine grausame Bitte.',
    ('Text/Event/Mura/Fumoto/EventMain.csvtxt', 'English#c:02000301_56'): 'Na, wie sich der Spieß gedreht hat.',
    ('Text/Event/Mura/Fumoto/EventMain.csvtxt', 'English#c:02000301_6'): 'In Ordnung. Es tut mir leid.',
    ('Text/Event/Mura/Fumoto/EventMain.csvtxt', 'English#c:02000301_7'): 'Lady Sakuna, wenn du bereit und imstande bist,\nkönnten wir wohl auf deine Hilfe zählen?',
    ('Text/Event/Mura/Fumoto/EventMain.csvtxt', 'English#c:02000301_8'): 'Es scheint aufzuziehen, also möchten wir\nheute das gesamte Pflanzen abschließen,\nwenn möglich.',
    ('Text/Event/Mura/Fumoto/EventMain.csvtxt', 'English#c:02000301_9'): 'Uuugh... schon wieder das?',
    ('Text/Event/Mura/Kaji/EventMain.csvtxt', 'English#c:07000301_0'): "Ich hab's endlich fertig!\nMein Schwert! Das beste Schwert aller Zeiten!",
    ('Text/Event/Mura/Kaji/EventMain.csvtxt', 'English#c:07000301_1'): '*seufz* Das hat ewig gedauuuuert.',
    ('Text/Event/Mura/Kaji/EventMain.csvtxt', 'English#c:07000301_2'): 'Tag für Tag mit dem Hammer auf heißes Metall...\nDas war alles dafür.\nEs ist endlich fertig.',
    ('Text/Event/Mura/Kaji/EventMain.csvtxt', 'English#c:07000301_3'): 'Kinta! Essen ist fertig!',
    ('Text/Event/Mura/Kaji/EventMain.csvtxt', 'English#c:07000301_4'): 'Ich komm sofort!',
    ('Text/Event/Mura/Kaji/EventMain.csvtxt', 'English#c:07000301_5'): 'Darf es keiner sehen, bevor es fertig ist.\nIch muss erst Griff und Scheide machen.\nDann zeige ich es her.',
    ('Text/Event/Mura/Kaji/EventMain.csvtxt', 'English#c:07000302_0'): 'Was ist los...? Kinta? Hallo?\nNiedriges Reich an Kinta, hörst du?',
    ('Text/Event/Mura/Kaji/EventMain.csvtxt', 'English#c:07000302_1'): 'Es ist weg.',
    ('Text/Event/Mura/Kaji/EventMain.csvtxt', 'English#c:07000302_10'): 'Du also im Ernst?',
    ('Text/Event/Mura/Kaji/EventMain.csvtxt', 'English#c:07000302_11'): 'Jemand wie du würde das nicht verstehen.',
    ('Text/Event/Mura/Kaji/EventMain.csvtxt', 'English#c:07000302_12'): 'Mrrrgh! Nun gut. Mach, wie du willst.',
    ('Text/Event/Mura/Kaji/EventMain.csvtxt', 'English#c:07000302_13'): 'S-Sei doch nicht so, Göttin!',
    ('Text/Event/Mura/Kaji/EventMain.csvtxt', 'English#c:07000302_14'): 'Entscheide dich endlich?!',
    ('Text/Event/Mura/Kaji/EventMain.csvtxt', 'English#c:07000302_15'): 'Ich verstehe. Als Schmied wolltest du ein Schwert\nschmieden, das Tauemons übertrifft.',
    ('Text/Event/Mura/Kaji/EventMain.csvtxt', 'English#c:07000302_16'): 'Ein solcher Wunsch ist nicht so ungewöhnlich.',
    ('Text/Event/Mura/Kaji/EventMain.csvtxt', 'English#c:07000302_17'): 'Das ist also die Grundidee, hm?',
    ('Text/Event/Mura/Kaji/EventMain.csvtxt', 'English#c:07000302_18'): 'Ja. Besonders für mich...',
    ('Text/Event/Mura/Kaji/EventMain.csvtxt', 'English#c:07000302_19'): 'Wie auch immer: Ein Schwert, von dem niemand wusste,\nkann nicht einfach so verschwinden.',
    ('Text/Event/Mura/Kaji/EventMain.csvtxt', 'English#c:07000302_2'): 'Was ist weg?',
    ('Text/Event/Mura/Kaji/EventMain.csvtxt', 'English#c:07000302_20'): 'Und außerdem waren alle nach dem Abendessen\nvollzählig.',
    ('Text/Event/Mura/Kaji/EventMain.csvtxt', 'English#c:07000302_21'): 'Hmmm... Ich spüre eine schwache Kraft\naus diesem Schuppen.',
    ('Text/Event/Mura/Kaji/EventMain.csvtxt', 'English#c:07000302_22'): 'Kinta, ich habe eine Frage, wenn du mir erlaubst.\nWoher hast du das Material für dieses\nSchwert?',
    ('Text/Event/Mura/Kaji/EventMain.csvtxt', 'English#c:07000302_23'): 'Ich bin mit dem Hund rausgeschlichen und hab es gesammelt.\nAshigumo hat mir auch geholfen.',
    ('Text/Event/Mura/Kaji/EventMain.csvtxt', 'English#c:07000302_24'): 'Dieser Ashigumo... Wir haben uns zu sehr auf ihn verlassen.\nDass er so viel für uns tat...',
    ('Text/Event/Mura/Kaji/EventMain.csvtxt', 'English#c:07000302_25'): 'Er ist wahrlich ein tapferer Verbündeter.',
    ('Text/Event/Mura/Kaji/EventMain.csvtxt', 'English#c:07000302_26'): 'Mann, jetzt fühle ich mich echt mies.',
    ('Text/Event/Mura/Kaji/EventMain.csvtxt', 'English#c:07000302_27'): 'Du hast also Bernstein als Material verwendet?',
    ('Text/Event/Mura/Kaji/EventMain.csvtxt', 'English#c:07000302_28'): 'Ja. Ich hörte, er steckt voll göttlicher Kraft,\nda musste ich ihn nehmen.',
    ('Text/Event/Mura/Kaji/EventMain.csvtxt', 'English#c:07000302_29'): 'Du handelst nach jedem flüchtigen Gedanken,\nder dir einfällt, oder?',
    ('Text/Event/Mura/Kaji/EventMain.csvtxt', 'English#c:07000302_3'): 'Das Schwert...',
    ('Text/Event/Mura/Kaji/EventMain.csvtxt', 'English#c:07000302_30'): 'Bernstein birgt nicht nur göttliche Kraft.',
    ('Text/Event/Mura/Kaji/EventMain.csvtxt', 'English#c:07000302_31'): 'Ist genug davon gesammelt, kann er die Seele\neines göttlichen Wesens bilden. Mit anderen Worten:\nAus Bernstein werden Götter geboren.',
    ('Text/Event/Mura/Kaji/EventMain.csvtxt', 'English#c:07000302_32'): 'Schmolzest du das und es Hunderttausende Male\nzum Schwert hämmertest,\ndann...',
    ('Text/Event/Mura/Kaji/EventMain.csvtxt', 'English#c:07000302_33'): 'Könnte es sein...?!',
    ('Text/Event/Mura/Kaji/EventMain.csvtxt', 'English#c:07000302_34'): 'Hab ich... einen Gott erschaffen?!',
    ('Text/Event/Mura/Kaji/EventMain.csvtxt', 'English#c:07000302_35'): 'Sehr wahrscheinlich, ja.',
    ('Text/Event/Mura/Kaji/EventMain.csvtxt', 'English#c:07000302_36'): 'Für einen Menschen ist das eine erstaunliche Tat.',
    ('Text/Event/Mura/Kaji/EventMain.csvtxt', 'English#c:07000302_37'): 'Nun... Selbst wenn er es geschafft hat, der Gott\nin Frage ist ein neugeborenes Kind.',
    ('Text/Event/Mura/Kaji/EventMain.csvtxt', 'English#c:07000302_38'): 'Wir müssen zuerst im Pass nach ihm suchen.',
    ('Text/Event/Mura/Kaji/EventMain.csvtxt', 'English#c:07000302_4'): 'Schwert? Meinst du Tauemons Klinge?',
    ('Text/Event/Mura/Kaji/EventMain.csvtxt', 'English#c:07000302_5'): 'Nein, nicht das!',
    ('Text/Event/Mura/Kaji/EventMain.csvtxt', 'English#c:07000302_6'): 'Sei dann konkreter!\nWir verstehen dich nicht!',
    ('Text/Event/Mura/Kaji/EventMain.csvtxt', 'English#c:07000302_7'): 'Das Schwert, das ich geschmiedet habe...',
    ('Text/Event/Mura/Kaji/EventMain.csvtxt', 'English#c:07000302_8'): 'Was?! Du hast ein Schwert geschmiedet?\nHier, in diesem Pass?!',
    ('Text/Event/Mura/Kaji/EventMain.csvtxt', 'English#c:07000302_9'): 'Jetzt, wo ich darüber nachdenke, hast du\ndas damals erwähnt, als wir gerade\nangefangen haben.',
    ('Text/Event/Mura/Kaji/EventMain.csvtxt', 'English#c:07000702_0'): 'Das alles liegt an meiner Unerfahrenheit!',
    ('Text/Event/Mura/Kaji/EventMain.csvtxt', 'English#c:07000702_1'): 'Es tut mir so leid!',
    ('Text/Event/Mura/Kaji/EventMain.csvtxt', 'English#c:07000702_10'): 'Keine Sorge. Nutzt du sowohl Griff als Klinge,\nbleibt meine Seele bewahrt.',
    ('Text/Event/Mura/Kaji/EventMain.csvtxt', 'English#c:07000702_11'): 'Huh. Okay, ich mach das.',
    ('Text/Event/Mura/Kaji/EventMain.csvtxt', 'English#c:07000702_12'): 'Vorher fühlte ich mich etwas erstickt, doch nun,\ndass ich weiß, wie weit es noch ist, bin ich\nglücklicher denn je.',
    ('Text/Event/Mura/Kaji/EventMain.csvtxt', 'English#c:07000702_13'): 'Den Schwertgeist neu zu bearbeiten, der mich das lehrte,\nist eine Ehre, die mir zu groß ist.',
    ('Text/Event/Mura/Kaji/EventMain.csvtxt', 'English#c:07000702_14'): 'Diese zuckersüße Schwafelei verdirbt mir rasch die Laune.\nWerde ich morgen aufwachen und Schweine am Himmel\nvor meinem Fenster sehen?',
    ('Text/Event/Mura/Kaji/EventMain.csvtxt', 'English#c:07000702_15'): 'Halt die Klappe, du falsche Faulpelz-Göttin!\nGib mir schon dieses Schwert!',
    ('Text/Event/Mura/Kaji/EventMain.csvtxt', 'English#c:07000702_16'): 'Ho ho ho!',
    ('Text/Event/Mura/Kaji/EventMain.csvtxt', 'English#c:07000702_2'): 'Ich wollte so sehr etwas Besseres machen als das Schwert\nvom Alten. Aber alles hat seine Grenzen.',
    ('Text/Event/Mura/Kaji/EventMain.csvtxt', 'English#c:07000702_3'): 'Huh. Unerwartet tiefe Worte\nfür einen Blag wie dich.',
    ('Text/Event/Mura/Kaji/EventMain.csvtxt', 'English#c:07000702_4'): 'Sei still, du...',
    ('Text/Event/Mura/Kaji/EventMain.csvtxt', 'English#c:07000702_5'): 'Wollte ich nicht was für dich machen?',
    ('Text/Event/Mura/Kaji/EventMain.csvtxt', 'English#c:07000702_6'): 'Ah, ja. Mit dieser Klinge\ndes Hoshidama.',
    ('Text/Event/Mura/Kaji/EventMain.csvtxt', 'English#c:07000702_7'): 'Ganz einfach: Das ist Tama selbst:\nein besonderes Schwert aus astralischem Metall.',
    ('Text/Event/Mura/Kaji/EventMain.csvtxt', 'English#c:07000702_8'): 'Könntest du das schmelzen und damit das stärkste\nAckerwerkzeug herstellen, das je gemacht wurde?',
    ('Text/Event/Mura/Kaji/EventMain.csvtxt', 'English#c:07000702_9'): 'Wird Tama das schaden, wenn ich das tue?',
}

